  38|// setupTestRepoWithMainBranch creates a temporary bare git repo with the default
  39|// branch explicitly set to "main". This is required by tests that branch
  40|// off "main" by name (e.g., createFeatureWorktree).
  41|func setupTestRepoWithMainBranch(t *testing.T) string {
  42|	t.Helper()
  43|	bareRepoPath := testutil.SetupBareRepo(t)
  44|	// Detect the current default branch and rename it to "main" if needed.
  45|	defaultBranch, err := testutil.RunGit([]string{"symbolic-ref", "--short", "HEAD"}, bareRepoPath)
  46|	if err != nil {
  47|		t.Fatalf("detect default branch: %v", err)
  48|	}
  49|	if defaultBranch != "main" {
  50|		if _, err := testutil.RunGit([]string{"branch", "-m", defaultBranch, "main"}, bareRepoPath); err != nil {
  51|			t.Fatalf("rename branch to main: %v", err)
  52|		}
  53|		if _, err := testutil.RunGit([]string{"symbolic-ref", "HEAD", "refs/heads/main"}, bareRepoPath); err != nil {
  54|			t.Fatalf("set HEAD to main: %v", err)
  55|		}
  56|	}
  57|	return bareRepoPath
  58|}
