  70|// createFeatureWorktree creates a feature worktree in the bare repo.
  71|func createFeatureWorktree(t *testing.T, bareRepoPath, featureName string) string {
  72|	t.Helper()
  73|	featureDir := filepath.Join(bareRepoPath, "feature", featureName, "integration")
  74|	branchName := "feature/" + featureName
  75|	if err := os.MkdirAll(filepath.Dir(featureDir), 0o755); err != nil {
  76|		t.Fatal(err)
  77|	}
  78|	if _, err := worktree.RunGit([]string{"branch", branchName, "main"}, bareRepoPath); err != nil {
  79|		t.Fatalf("create branch %s: %v", branchName, err)
  80|	}
  81|	if _, err := worktree.RunGit([]string{"worktree", "add", featureDir, branchName}, bareRepoPath); err != nil {
  82|		t.Fatalf("add worktree %s: %v", branchName, err)
  83|	}
  84|	worktree.RunGit([]string{"config", "user.email", "test@test.com"}, featureDir)
  85|	worktree.RunGit([]string{"config", "user.name", "Test"}, featureDir)
  86|	return featureDir
  87|}
