  89|// createAgentBranch creates an agent branch off the feature branch
  90|// and optionally adds a commit. Returns the branch name.
  91|func createAgentBranch(t *testing.T, bareRepoPath, featureName, branchName string, addCommit bool) string {
  92|	t.Helper()
  93|	featureDir := filepath.Join(bareRepoPath, "feature", featureName, "integration")
  94|	agentDir := filepath.Join(bareRepoPath, "feature", featureName, "agent-test")
  95|	featureBranch := "feature/" + featureName
  96|
  97|	// Create agent branch from feature branch.
  98|	if _, err := worktree.RunGit([]string{"branch", branchName, featureBranch}, bareRepoPath); err != nil {
  99|		t.Fatalf("create branch %s: %v", branchName, err)
 100|	}
 101|	if err := os.MkdirAll(filepath.Dir(agentDir), 0o755); err != nil {
 102|		t.Fatal(err)
 103|	}
 104|	if _, err := worktree.RunGit([]string{"worktree", "add", agentDir, branchName}, bareRepoPath); err != nil {
 105|		t.Fatalf("add worktree %s: %v", branchName, err)
 106|	}
 107|	worktree.RunGit([]string{"config", "user.email", "test@test.com"}, agentDir)
 108|	worktree.RunGit([]string{"config", "user.name", "Test"}, agentDir)
 109|
 110|	if addCommit {
 111|		testFile := filepath.Join(agentDir, "agent-work.txt")
 112|		if err := os.WriteFile(testFile, []byte("agent work"), 0o644); err != nil {
 113|			t.Fatal(err)
 114|		}
 115|		if _, err := worktree.RunGit([]string{"add", "."}, agentDir); err != nil {
 116|			t.Fatalf("git add: %v", err)
 117|		}
 118|		if _, err := worktree.RunGit([]string{"commit", "-m", "agent work commit"}, agentDir); err != nil {
 119|			t.Fatalf("commit: %v", err)
 120|		}
 121|	}
 122|
 123|	// Merge agent branch into feature to simulate already-merged.
 124|	if _, err := worktree.RunGit([]string{"merge", "--no-ff", branchName, "-m", "merge agent"}, featureDir); err != nil {
 125|		t.Fatalf("merge %s into feature: %v", branchName, err)
 126|	}
 127|
 128|	return branchName
 129|}
