 296|// ingestBugReports scans the bug report drop directory and inserts valid
 297|// reports into the database. After ingestion, newly inserted reports are
 298|// classified and promoted into tasks. Errors are logged and do not halt the tick.
 299|// doTick is a single iteration of the orchestrator loop.
 300|func (o *Orchestrator) doTick(ctx context.Context) {
 301|	_ = ctx
 302|	// 0. Ingest any pending bug reports from the drop directory.
 303|	o.ingestBugReports()
 304|	// 0b. Process CLASSIFYING tasks -> spawn classifier agents or call API directly.
 305|	if o.directClassifierCfg != nil {
 306|		o.processClassifyingTasksDirect()
 307|	} else {
 308|		o.processClassifyingTasks()
 309|	}
 310|	// 1. Process BACKLOG tasks -> transition to PLANNING.
 311|	// Root tasks with unmet dependencies remain in BACKLOG (pending).
 312|	var backlogTasks []model.Task
 313|	if err := o.db.Where("project_id = ? AND status = ? AND parent_task_id IS NULL", o.projectID, model.StatusBacklog).
 314|		Find(&backlogTasks).Error; err != nil {
 315|		o.logger.Error("query backlog tasks", "error", err)
 316|	}
 317|	for i := range backlogTasks {
 318|		task := &backlogTasks[i]
 319|		if len(task.DependencyIDs) > 0 {
 320|			met, err := DependenciesMet(o.db, task.DependencyIDs)
 321|			if err != nil {
 322|				o.logger.Error("check root task dependencies", "task_id", task.ID, "error", err)
 323|				continue
 324|			}
 325|			if !met {
 326|				continue
 327|			}
 328|		}
 329|		if err := o.processBacklog(task); err != nil {
 330|			o.logger.Error("process backlog", "task_id", task.ID, "error", err)
 331|		}
 332|	}
 333|
 334|	// 2. Drain agent completions.
 335|	completions := o.runner.DrainCompletions()
 336|	for _, comp := range completions {
 337|		if err := o.processAgentResult(comp); err != nil {
 338|			o.logger.Error("process agent result", "agent_id", comp.AgentID, "error", err)
 339|		}
 340|	}
 341|
 342|	// 2b. Check context window usage and apply role-aware escalation.
 343|	o.checkContextUsage()
 344|
 345|	// 2c. Fallback: detect agents stuck as WORKING whose idle signal file
 346|	// exists but was never picked up (e.g. notification hook failed to fire).
 347|	o.recoverStuckAgents()
