  46|
  47|// Delay returns the backoff duration for the given attempt number (1-based),
  48|// including random jitter.
  49|func (p ConstraintGatePolicy) Delay(attempt int) time.Duration {
  50|	if attempt < 1 {
  51|		attempt = 1
  52|	}
  53|	d := p.BaseDelay
  54|	for i := 1; i < attempt; i++ {
  55|		d *= 2
  56|	}
  57|	if p.MaxDelay > 0 && d > p.MaxDelay {
  58|		d = p.MaxDelay
  59|	}
  60|	// Add jitter: multiply by (1 + rand[0, 0.5))
  61|	jitter := time.Duration(rand.Float64() * 0.5 * float64(d))
  62|	return d + jitter
