package orchestrator

import (
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/godinj/drem-orchestrator/internal/model"
	"github.com/godinj/drem-orchestrator/internal/testutil"
	"github.com/godinj/drem-orchestrator/internal/worktree"
)

func TestConstraintGateWiring_ExhaustionState_MaxRetries(t *testing.T) {
	bareRepoPath := setupTestRepoWithMainBranch(t)
	setupMainWorktreeWithConstraints(t, bareRepoPath, "[[max_lines]]\nname = \"file size check\"\nglob = \"*.go\"\nlimit = 5\n")
	featureName := "gate-retry-max-exhaustion"
	featureDir := constraintFailWorktree(t, bareRepoPath, featureName, 5)
	expectedSHA := runGitCmd(t, featureDir, "rev-parse", "HEAD")

	db := testutil.NewTestDB(t)
	wt := &worktree.Manager{BareRepoPath: bareRepoPath, DefaultBranch: "main"}
	o := testOrchestrator(t, db, wt)

	project := model.Project{ID: o.projectID, Name: "test", BareRepoPath: bareRepoPath}
	db.Create(&project)

	pastCheck := time.Now().Add(-1 * time.Minute).Format(time.RFC3339)
	parentID := uuid.New()
	parent := model.Task{
		ID:             parentID,
		ProjectID:      o.projectID,
		Title:          "parent",
		Description:    "test parent",
		Status:         model.StatusTestWriting,
		WorktreeBranch: "feature/" + featureName,
		Context: model.JSONField{
			"baseline_tests_checked":          true,
			"constraint_gate_retries":         float64(MaxConstraintGateRetries - 1),
			"constraint_gate_next_check":      pastCheck,
			"constraint_gate_previous_failed": float64(1),
		},
	}
	db.Create(&parent)

	sub := model.Task{
		ID:           uuid.New(),
		ProjectID:    o.projectID,
		ParentTaskID: &parentID,
		Title:        "test-sub",
		Description:  "test subtask",
		Status:       model.StatusDone,
		Phase:        "test",
	}
	db.Create(&sub)

	if err := o.processTestWriting(&parent); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	var updated model.Task
	db.First(&updated, "id = ?", parentID)

	if updated.Status != model.StatusFailed {
		t.Errorf("expected status failed, got %s", updated.Status)
	}

	exhausted, ok := updated.Context["constraint_gate_exhausted"].(bool)
	if !ok || !exhausted {
		t.Errorf("expected constraint_gate_exhausted=true, got %v", updated.Context["constraint_gate_exhausted"])
	}

	failedAtCommit, ok := updated.Context["constraint_gate_failed_at_commit"].(string)
	if !ok || failedAtCommit != expectedSHA {
		t.Errorf("expected constraint_gate_failed_at_commit=%s, got %s", expectedSHA, failedAtCommit)
	}
}

func TestConstraintGateWiring_ExhaustionState_EarlyTermination(t *testing.T) {
	bareRepoPath := setupTestRepoWithMainBranch(t)
	featureName := "gate-retry-early-term-exhaustion"

